-- Fiktiver Grundriss für den Hauptsitz Zürich (Standort 9) samt Hotspots für die Plan-Screenshots.
-- Läuft einmal auf seed.sql auf. Zusätzlich Check-in auf Rigi mit einer Buchung um 14 Uhr und eine Ressourcenfarbe auf Jungfrau, damit die Planfarben sichtbar sind.
SET NOCOUNT ON; SET XACT_ABORT ON;
IF EXISTS (SELECT 1 FROM Planmarkierung WHERE StandortId = 9) THROW 50000, 'seed-buchen-kalender-plan.sql wurde schon eingespielt.', 1;
BEGIN TRANSACTION;
DECLARE @svg varchar(max) = '';
SET @svg = @svg + '<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="900" viewBox="0 0 1400 900"><rect width="1400" height="900" fill="#fbfbf8"/><rect x="40" y="40" width="1320" height="640" fill="#f1f0ea" stroke="#333" stroke-width="10"/><rect x="60" y="60" width="320" height="240" fill="#ffffff" stroke="#444" stroke-width="4"/><text x="220" y="96" font-family="Arial" font-size="22" fill="#555" text-anchor="middle">Jungfrau</text><rect x="400" y="60" width="240" height="240" fill="#ffffff" stroke="#444" stroke-width="4"/><text x="520" y="96" font-family="Arial" font-size="22" fill="#555" text-anchor="middle">Eiger</text><rect x="660" y="60" width="200" height="240" fill="#ffffff" stroke="#444" stroke-width="4"/><text x="760" y="96" font-family="Arial" font-size="22" fill="#555" text-anchor="middle">M&#246;nch</text><rect x="880" y="60" width="180" height="240" fill="#ffffff" stroke="#444" stroke-width="4"/><text x="970" y="96" font-family="Arial" font-size="22" fill="#555" text-anchor="middle">Pilatus</text><rect x="1080" y="60" width="260" height="240" fill="#ffffff" stroke="#444" stroke-width="4"/><text x="1210" y="96" font-family="Arial" font-size="22" fill="#555" text-anchor="middle">Rigi</text><text x="700" y="350" font-family="Arial" font-size="20" fill="#888" text-anchor="middle">Korridor</text><path d="M60 400 H470 V660 H230 V560 H60 Z" fill="#fff" stroke="#444" stroke-width="4"/><text x="280" y="436" font-family="Arial" font-size="22" fill="#555" text-anchor="middle">S&#228;ntis</text><rect x="500" y="400" width="140" height="120" fill="#e8e6dd" stroke="#444" stroke-width="4"/><text x="570" y="470" font-family="Arial" font-size="18" fill="#777" text-anchor="middle">Empfang</text><rect x="500" y="540" width="140" height="120" fill="#e8e6dd" stroke="#444" stroke-width="4"/><text x="570" y="610" font-family="Arial" font-size="18" fill="#777" text-anchor="middle">K&#252;che</text><rect x="670" y="400" width="670" height="260" fill="#ffffff" stroke="#444" stroke-width="4"/><text x="1005" y="436" font-family="Arial" font-size="22" fill="#555" text-anchor="middle">Open Space</text><rect x="710" y="550" width="100" height="40" fill="#ddd" stroke="#888" stroke-width="2"/><rect x="870" y="550" width="100" height="40" fill="#ddd" stroke="#888" stroke-width="2"/><rect x="1030" y="550" width="100" height="40" fill="#ddd" stroke="#888" stroke-width="2"/><rect x="1190" y="550" width="100" height="40" fill="#ddd" stroke="#888" stroke-width="2"/><text x="150" y="740" font-family="Arial" font-size="20" fill="#888" text-anchor="middle">Aussenparkpl&#228;tze</text><rect x="320" y="720" width="100" height="150" fill="none" stroke="#888" stroke-width="3"/><rect x="440" y="720" width="100" height="150" fill="none" stroke="#888" stroke-width="3"/><rect x="560" y="720" width="100" height="150" fill="none" stroke="#888" stroke-width="3"/></svg>';
UPDATE Standort SET PlanData = CAST(@svg AS varbinary(max)), PlanBreite = 1400, [PlanHöhe] = 900, PlanZoomstufen = 5 WHERE Id = 9;
INSERT Planmarkierung(StandortId,RessourceLinkId,Koordinaten,GeomType) SELECT 9,Id,'70,-110,370,-110,370,-290,70,-290,70,-110','Polygon' FROM Ressource WHERE Name=N'Jungfrau' AND StandortId=9;
INSERT Planmarkierung(StandortId,RessourceLinkId,Koordinaten,GeomType) SELECT 9,Id,'410,-110,630,-110,630,-290,410,-290,410,-110','Polygon' FROM Ressource WHERE Name=N'Eiger' AND StandortId=9;
