INSERT Planmarkierung(StandortId,RessourceLinkId,Koordinaten,GeomType) SELECT 9,Id,'890,-110,1050,-110,1050,-290,890,-290,890,-110','Polygon' FROM Ressource WHERE Name=N'Pilatus' AND StandortId=9;
