INSERT Planmarkierung(StandortId,RessourceLinkId,Koordinaten,GeomType) SELECT 9,Id,'448,-730,532,-730,532,-860,448,-860,448,-730','Polygon' FROM Ressource WHERE Name=N'Parkplatz P2' AND StandortId=9;
INSERT Planmarkierung(StandortId,RessourceLinkId,Koordinaten,GeomType) SELECT 9,Id,'568,-730,652,-730,652,-860,568,-860,568,-730','Polygon' FROM Ressource WHERE Name=N'Parkplatz E1' AND StandortId=9;
UPDATE Ressource SET CheckinAktiviert = 1 WHERE Name = N'Rigi' AND StandortId = 9;
UPDATE Ressource SET Farbe = '#7c3aed' WHERE Name = N'Jungfrau' AND StandortId = 9;
DECLARE @heute date = CAST(GETDATE() AS date);
DECLARE @von datetime = CAST(CAST(DATEADD(hour, 13, CAST(@heute AS datetime)) AS datetime2) AT TIME ZONE 'W. Europe Standard Time' AT TIME ZONE 'UTC' AS datetime);
DECLARE @bis datetime = DATEADD(hour, 3, @von);
INSERT Reservation(RessourceId,RessourcetypId,StatusId,PersonOrganisatorId,PersonErstellerId,Titel,Vorlaufbeginn,Beginn,Ende,Nachlaufende,AnzahlPersonen,IstPrivat,IstPersonRessourceReservation,Delay,IstCheckinBestaetigt,CreatedOn,ModifiedOn,MaskedIdentifier,FreeBusyStatus,IsTeamsMeeting,SyncDisabled,IsLocked,AllDayEvent)
SELECT r.Id,r.RessourcetypId,4,5,5,N'Fokustag Kampagne',@von,@von,@bis,@bis,3,0,0,0,0,GETUTCDATE(),GETUTCDATE(),NEWID(),'Busy',0,0,0,0 FROM Ressource r WHERE r.Name = N'Rigi' AND r.StandortId = 9;
-- Rolle Superuser (30): Reiter Reminder in der Detailbuchung sichtbar machen.
INSERT RolleRecht(RolleId,RechtId,GueltigkeitDauer,IstInTagen,IstAblaufend,IstImportiert) VALUES(30,147,0,0,0,0);
-- Thomas Meier synchronisiert seine Buchungen, damit die Massen-Schnellbuchung die Spalte Sync zeigt.
UPDATE Person SET SettingsXml.modify('insert (<SyncMode>Microsoft365</SyncMode>, <SynchronisationReservationEigene>true</SynchronisationReservationEigene>, <SyncRaum>true</SyncRaum>) as first into (/PersonSettings)[1]') WHERE Id = 4;
COMMIT;
SELECT COUNT(*) Hotspots FROM Planmarkierung WHERE StandortId = 9;
